import { inject } from "vue";
import type { InjectionKey, Ref } from "vue";

export interface SidebarContext {
  collapsed: Ref<boolean>;
  openMobile: Ref<boolean>;
  isMobile: Ref<boolean>;
  toggle: () => void;
}

export const sidebarKey: InjectionKey<SidebarContext> = Symbol("vitehub-sidebar");

export function useSidebar(): SidebarContext {
  const context = inject(sidebarKey, null);
  if (!context) throw new Error("useSidebar() needs a <SidebarProvider> above it. Wrap the layout in <SidebarProvider>.");
  return context;
}

export { default as Sidebar } from "./Sidebar.vue";
export { default as SidebarContent } from "./SidebarContent.vue";
export { default as SidebarFooter } from "./SidebarFooter.vue";
export { default as SidebarGroup } from "./SidebarGroup.vue";
export { default as SidebarGroupContent } from "./SidebarGroupContent.vue";
export { default as SidebarGroupLabel } from "./SidebarGroupLabel.vue";
export { default as SidebarHeader } from "./SidebarHeader.vue";
export { default as SidebarInset } from "./SidebarInset.vue";
export { default as SidebarMenu } from "./SidebarMenu.vue";
export { default as SidebarMenuBadge } from "./SidebarMenuBadge.vue";
export { default as SidebarMenuButton } from "./SidebarMenuButton.vue";
export { default as SidebarMenuItem } from "./SidebarMenuItem.vue";
export { default as SidebarMenuSub } from "./SidebarMenuSub.vue";
export { default as SidebarMenuSubButton } from "./SidebarMenuSubButton.vue";
export { default as SidebarMenuSubItem } from "./SidebarMenuSubItem.vue";
export { default as SidebarProvider } from "./SidebarProvider.vue";
export { default as SidebarSeparator } from "./SidebarSeparator.vue";
export { default as SidebarTrigger } from "./SidebarTrigger.vue";
export { sidebarKey, useSidebar } from "./context.ts";
export type { SidebarContext } from "./context.ts";
export type * from "./types.ts";

@layer components {
  /* Sidebar: a 16rem column in `--vh-sidebar` beside the page. It collapses to a 3rem rail of icons or off the canvas. */
  [data-slot="sidebar-wrapper"] {
    --sidebar-width: 16rem;
    --sidebar-width-icon: 3rem;

    display: flex;
    min-height: 100svh;
    width: 100%;
  }

  [data-slot="sidebar"] {
    color: var(--vh-sidebar-text);
    display: none;
  }

  [data-slot="sidebar"][data-collapsible="none"] {
    background: var(--vh-sidebar);
    display: flex;
    flex-direction: column;
    height: 100%;
    width: var(--sidebar-width);
  }

  [data-slot="sidebar"][data-collapsible="none"] > [data-slot="sidebar-gap"] {
    display: none;
  }

  [data-slot="sidebar"][data-collapsible="none"] > [data-slot="sidebar-container"] {
    display: contents;
  }

  @media (min-width: 768px) {
    [data-slot="sidebar"] {
      display: block;
    }

    [data-slot="sidebar"][data-collapsible="none"] {
      display: flex;
    }
  }

  [data-slot="sidebar-gap"] {
    position: relative;
    transition: width 200ms cubic-bezier(0.22, 1, 0.36, 1);
    width: var(--sidebar-width);
  }

  [data-slot="sidebar-container"] {
    bottom: 0;
    display: flex;
    height: 100svh;
    left: 0;
    position: fixed;
    top: 0;
    transition: left 200ms cubic-bezier(0.22, 1, 0.36, 1), right 200ms cubic-bezier(0.22, 1, 0.36, 1), width 200ms cubic-bezier(0.22, 1, 0.36, 1);
    width: var(--sidebar-width);
    z-index: 10;
  }

  [data-slot="sidebar"][data-side="left"] > [data-slot="sidebar-container"] {
    border-inline-end: 1px solid var(--vh-sidebar-border);
  }

  [data-slot="sidebar"][data-side="right"] > [data-slot="sidebar-container"] {
    border-inline-start: 1px solid var(--vh-sidebar-border);
    left: auto;
    right: 0;
  }

  [data-slot="sidebar-inner"] {
    background: var(--vh-sidebar);
    display: flex;
    flex-direction: column;
    height: 100%;
    overflow: hidden;
    width: 100%;
  }

  [data-slot="sidebar"][data-collapsed][data-collapsible="icon"] > [data-slot="sidebar-gap"],
  [data-slot="sidebar"][data-collapsed][data-collapsible="icon"] > [data-slot="sidebar-container"] {
    width: var(--sidebar-width-icon);
  }

  [data-slot="sidebar"][data-collapsed][data-collapsible="offcanvas"] > [data-slot="sidebar-gap"] {
    width: 0;
  }

  [data-slot="sidebar"][data-collapsed][data-collapsible="offcanvas"][data-side="left"] > [data-slot="sidebar-container"] {
    left: calc(var(--sidebar-width) * -1);
  }

  [data-slot="sidebar"][data-collapsed][data-collapsible="offcanvas"][data-side="right"] > [data-slot="sidebar-container"] {
    right: calc(var(--sidebar-width) * -1);
  }

  @media (prefers-reduced-motion: reduce) {
    :is([data-slot="sidebar-gap"], [data-slot="sidebar-container"], [data-slot="sidebar-group-label"]) {
      transition: none;
    }
  }

  /* The mobile sheet. ui-sdk's drawer viewport puts it on its `data-side`. */
  [data-slot="sidebar-overlay"] {
    background: var(--vh-overlay);
    inset: 0;
    position: fixed;
    z-index: 50;
  }

  [data-slot="sidebar-overlay"][data-hidden] {
    display: none;
  }

  [data-slot="drawer-content"][data-sidebar] {
    background: var(--vh-sidebar);
    box-shadow: var(--vh-shadow-dialog);
    display: flex;
    flex-direction: column;
    height: 100%;
    max-width: 85vw;
    outline: none;
    padding: 0;
    width: var(--sidebar-width, 16rem);
  }

  [data-slot="drawer-content"][data-sidebar]::after {
    content: none;
  }

  [data-slot="sidebar-title"] {
    clip-path: inset(50%);
    height: 1px;
    overflow: hidden;
    position: absolute;
    white-space: nowrap;
    width: 1px;
  }

  [data-slot="sidebar-inset"] {
    background: var(--vh-bg);
    display: flex;
    flex: 1;
    flex-direction: column;
    min-width: 0;
    position: relative;
    width: 100%;
  }

  [data-slot="sidebar-trigger"] {
    align-items: center;
    background: transparent;
    border: 0;
    border-radius: calc(var(--vh-radius) * 0.75);
    color: var(--vh-muted);
    cursor: pointer;
    display: inline-flex;
    flex: none;
    height: 1.75rem;
    justify-content: center;
    padding: 0;
    transition: background-color 150ms ease-out, color 150ms ease-out;
    width: 1.75rem;
  }

  @media (hover: hover) {
    [data-slot="sidebar-trigger"]:hover {
      background: var(--vh-bg-muted);
      color: var(--vh-text);
    }
  }

  [data-slot="sidebar-trigger"] > svg {
    height: 1rem;
    width: 1rem;
  }

  [data-slot="sidebar-trigger"] > svg:is([dir="rtl"] *) {
    rotate: 180deg;
  }

  :is([data-slot="sidebar-header"], [data-slot="sidebar-footer"]) {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 0.5rem;
  }

  [data-slot="sidebar-footer"] {
    margin-top: auto;
  }

  [data-slot="sidebar-content"] {
    display: flex;
    flex: 1;
    flex-direction: column;
    gap: 0.5rem;
    min-height: 0;
    overflow: auto;
    padding-inline: 0.25rem;
  }

  [data-slot="sidebar"][data-collapsed][data-collapsible="icon"] [data-slot="sidebar-content"] {
    overflow: hidden;
  }

  [data-slot="sidebar-group"] {
    display: flex;
    flex-direction: column;
    min-width: 0;
    padding: 0.25rem;
    position: relative;
    width: 100%;
  }

  [data-slot="sidebar-group-label"] {
    align-items: center;
    color: var(--vh-dimmed);
    display: flex;
    flex: none;
    font-size: 0.75rem;
    font-weight: 500;
    height: 2rem;
    padding-inline: 0.5rem;
    transition: margin 200ms ease-out, opacity 200ms ease-out;
  }

  [data-slot="sidebar"][data-collapsed][data-collapsible="icon"] [data-slot="sidebar-group-label"] {
    margin-top: -2rem;
    opacity: 0;
  }

  :is([data-slot="sidebar-menu"], [data-slot="sidebar-menu-sub"]) {
    display: flex;
    flex-direction: column;
    gap: 0.125rem;
    list-style: none;
    margin: 0;
    min-width: 0;
    padding: 0;
  }

  :is([data-slot="sidebar-menu-item"], [data-slot="sidebar-menu-sub-item"]) {
    position: relative;
  }

  :is([data-slot="sidebar-menu-button"], [data-slot="sidebar-menu-sub-button"]) {
    align-items: center;
    background: transparent;
    border: 0;
    border-radius: calc(var(--vh-radius) * 0.75);
    color: var(--vh-sidebar-text);
    cursor: pointer;
    display: flex;
    font: inherit;
    font-size: 0.875rem;
    gap: 0.5rem;
    height: 2rem;
    min-width: 0;
    overflow: hidden;
    padding-inline: 0.5rem;
    text-align: start;
    text-decoration: none;
    transition: background-color 150ms ease-out, color 150ms ease-out;
    width: 100%;
  }

  [data-slot="sidebar-menu-button"][data-size="sm"] {
    font-size: 0.75rem;
    height: 1.75rem;
  }

  [data-slot="sidebar-menu-button"][data-size="lg"] {
    height: 3rem;
  }

  [data-slot="sidebar-menu-sub-button"] {
    color: var(--vh-muted);
    height: 1.75rem;
  }

  @media (hover: hover) {
    :is([data-slot="sidebar-menu-button"], [data-slot="sidebar-menu-sub-button"]):hover:not(:disabled) {
      background: var(--vh-sidebar-accent);
      color: var(--vh-text);
    }
  }

  :is([data-slot="sidebar-menu-button"], [data-slot="sidebar-menu-sub-button"])[data-active] {
    background: var(--vh-sidebar-accent);
    color: var(--vh-text);
    font-weight: 500;
  }

  /* The list clips the rows, so the ring stays inside the row. */
  :is([data-slot="sidebar-menu-button"], [data-slot="sidebar-menu-sub-button"]):focus-visible {
    outline: 2px solid var(--vh-ring);
    outline-offset: -2px;
  }

  :is([data-slot="sidebar-menu-button"], [data-slot="sidebar-menu-sub-button"]):disabled {
    cursor: not-allowed;
    opacity: 0.5;
  }

  :is([data-slot="sidebar-menu-button"], [data-slot="sidebar-menu-sub-button"]) > svg {
    flex: none;
    height: 1rem;
    width: 1rem;
  }

  [data-slot="sidebar-menu-button"] > svg:first-child {
    color: var(--vh-muted);
  }

  [data-slot="sidebar-menu-button"][data-active] > svg:first-child {
    color: inherit;
  }

  :is([data-slot="sidebar-menu-button"], [data-slot="sidebar-menu-sub-button"]) > span:last-child {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  [data-slot="sidebar"][data-collapsed][data-collapsible="icon"] [data-slot="sidebar-menu-button"] {
    height: 2rem;
    padding: 0.5rem;
    width: 2rem;
  }

  [data-slot="sidebar-menu-badge"] {
    align-items: center;
    border-radius: calc(var(--vh-radius) * 0.75);
    color: var(--vh-muted);
    display: flex;
    font-size: 0.75rem;
    font-variant-numeric: tabular-nums;
    font-weight: 500;
    height: 1.25rem;
    inset-block-start: 0.375rem;
    inset-inline-end: 0.375rem;
    justify-content: center;
    min-width: 1.25rem;
    padding-inline: 0.25rem;
    pointer-events: none;
    position: absolute;
    user-select: none;
  }

  [data-slot="sidebar-menu-sub"] {
    border-inline-start: 1px solid var(--vh-sidebar-border);
    margin-inline-start: 0.875rem;
    padding: 0.125rem 0.5rem;
  }

  [data-slot="sidebar"][data-collapsed][data-collapsible="icon"] :is([data-slot="sidebar-menu-badge"], [data-slot="sidebar-menu-sub"]) {
    display: none;
  }

  [data-slot="sidebar-separator"] {
    border: 0;
    border-top: 1px solid var(--vh-sidebar-border);
    margin: 0 0.5rem;
  }
}

export interface SidebarProviderProps {
  collapsed?: boolean;
  defaultCollapsed?: boolean;
}

export interface SidebarProviderEmits {
  "update:collapsed": [collapsed: boolean];
}

export interface SidebarProviderSlots {
  default?: (props: { isMobile: boolean; closeMobile: () => void }) => unknown;
}

export interface SidebarProps {
  side?: "left" | "right";
  collapsible?: "icon" | "offcanvas" | "none";
  label?: string;
}

export interface SidebarSlots {
  default?: () => unknown;
}

export interface SidebarTriggerProps {
  label?: string;
}

export interface SidebarTriggerSlots {
  icon?: () => unknown;
}

export interface SidebarGroupLabelProps {
  label?: string;
}

export interface SidebarMenuButtonProps {
  href?: string;
  isActive?: boolean;
  size?: "sm" | "md" | "lg";
  disabled?: boolean;
}

export interface SidebarMenuSubButtonProps {
  href?: string;
  isActive?: boolean;
  disabled?: boolean;
}

export interface SidebarMenuButtonRenderProps {
  "data-slot": string;
  "data-active"?: string;
  "data-size"?: string;
  "aria-current"?: "page";
  href?: string;
}

export interface SidebarMenuButtonSlots {
  default?: () => unknown;
  render?: (scope: { props: SidebarMenuButtonRenderProps }) => unknown;
}

export interface SidebarMenuSubButtonSlots {
  default?: () => unknown;
  render?: (scope: { props: SidebarMenuButtonRenderProps }) => unknown;
}

export interface SidebarInsetSlots {
  default?: () => unknown;
}

export interface SidebarHeaderSlots {
  default?: () => unknown;
}

export interface SidebarContentSlots {
  default?: () => unknown;
}

export interface SidebarFooterSlots {
  default?: () => unknown;
}

export interface SidebarGroupSlots {
  default?: () => unknown;
}

export interface SidebarGroupContentSlots {
  default?: () => unknown;
}

export interface SidebarMenuSlots {
  default?: () => unknown;
}

export interface SidebarMenuItemSlots {
  default?: () => unknown;
}

export interface SidebarMenuBadgeSlots {
  default?: () => unknown;
}

export interface SidebarMenuSubSlots {
  default?: () => unknown;
}

export interface SidebarMenuSubItemSlots {
  default?: () => unknown;
}

export interface SidebarGroupLabelSlots {
  default?: () => unknown;
}
